    for br in barrier_rows:
        for c in range(15):
            if result[br][c] == 0:
                for left in range(c-1, -1, -1):
                    if result[br][left] != 0:
                        result[br][c] = result[br][left]
                        break

    # Vertical fill for columns [3, 8]
    for c in [3, 8]:
