                if result[r][c] == 0:
                    result[r][c] = left_bottom

            # Fill BELOW bottom bar with bottom-right value (col 8)
            right_bottom = result[bottom][8]
            for r in range(bottom+1, 15):
                if result[r][c] == 0:
                    result[r][c] = right_bottom

    return result

